<template>
<section class="research-workflow" data-testid="research-workflow">
<header class="hero"><div><p class="eyebrow">MECH / RESEARCH OPERATIONS</p><h1>Research Workflow</h1><p>Compare prompts, inspect SAE features and logit lens projections, save reproducible experiments, and link results to existing tools.</p></div><button class="button secondary" :disabled="!hasFindings" @click="exportFindings">Export findings ↓</button></header>
<section class="panel"><div class="heading"><div><p class="eyebrow">01 / EXPERIMENT DESIGN</p><h2>Define a controlled comparison</h2></div><span class="tag">{{backendLabel}}</span></div>
<div class="fields"><label>Experiment title<input v-model="title" maxlength="120"></label><label>Model / SAE checkpoint A<input v-model="checkpoint" placeholder="gpt2 or SAE checkpoint ID"></label><label>SAE checkpoint B (optional)<input v-model="checkpointB" placeholder="Blank = same as checkpoint A"></label><label class="wide">Prompt A<textarea v-model="promptA" rows="2" maxlength="512"></textarea></label><label class="wide">Prompt B<textarea v-model="promptB" rows="2" maxlength="512"></textarea></label><label>SAE layer (optional)<input v-model="layer" type="number" min="0" step="1" placeholder="Backend default"></label><label>SAE source<select v-model="source"><option value="">Server default</option><option value="local">local</option><option value="configured">configured</option></select></label></div>
<div class="actions"><button class="button primary" :disabled="running||!promptA.trim()||!promptB.trim()" @click="runLens">{{running?'Running…':'Compare prompts · Logit Lens'}}</button><button class="button secondary" :disabled="running||!promptA.trim()||!promptB.trim()" @click="runSae">{{running?'Working…':'Inspect SAE features'}}</button></div><p class="hint">SAE checkpoint identifiers are request metadata interpreted by the SAE backend; they do not switch GPT-2 weights. Residual-stream comparisons use the backend’s active GPT-2 checkpoint only and require matching weight-derived fingerprints. Cross-checkpoint tensor comparison remains unavailable until the backend actually loads and attests both sets of weights.</p><p class="hint">Prompt A and B are filled by live GPT-2 generation on open and rotate automatically every 2 minutes. If GPT-2 is unavailable, no prewritten prompt is substituted.</p><p v-if="promptRotationNote" class="notice" role="status">{{promptRotationNote}}</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p></section>
<section class="panel" data-testid="live-cross-model-comparison">
<div class="heading"><div><p class="eyebrow">01B / LIVE MULTI-MODEL EXECUTION</p><h2>Cross-checkpoint comparison</h2></div><span class="tag">{{crossModelBusy?'LOADING REAL WEIGHTS':crossModelResult?'LIVE MEASUREMENT':'NO RUN YET'}}</span></div>
<p class="hint">Enter two real Hugging Face checkpoint IDs and revisions. MECH loads each independently, records resolved revisions and content fingerprints, compares only aligned tensor shapes, and stores completed live runs. Missing weights, incompatible shapes, or unavailable dependencies produce an explicit unavailable result—not a made-up metric.</p>
<div class="fields">
<label>Checkpoint A · Hugging Face repo ID<input v-model="compareModelA" placeholder="Enter checkpoint A (required)" autocomplete="off"></label>
<label>Checkpoint B · Hugging Face repo ID<input v-model="compareModelB" placeholder="Enter checkpoint B (required)" autocomplete="off"></label>
<label>Requested revision A<input v-model="compareRevisionA" placeholder="Commit hash, tag, or branch"></label>
<label>Requested revision B<input v-model="compareRevisionB" placeholder="Commit hash, tag, or branch"></label>
</div>
<div class="actions"><button class="button primary" :disabled="crossModelBusy||!promptA.trim()||!compareModelA.trim()||!compareModelB.trim()" @click="runCrossModelComparison">{{crossModelBusy?'Loading and measuring…':'Run live cross-model comparison'}}</button></div>
<p class="hint">Input prompt commitment: {{promptA.trim() ? promptA.trim().slice(0,160) : 'Waiting for generated prompt'}}{{promptA.trim().length>160?'…':''}}</p>
<p v-if="crossModelError" class="error" role="alert">{{crossModelError}}</p>
<div v-if="crossModelResult" class="comparison-results" data-testid="cross-model-result">
<div class="fields">
<div class="analysis-card"><h3>Checkpoint A</h3><p><strong>{{nestedText(crossModelModels.a,'repo_id_requested')||'—'}}</strong></p><p>Resolved revision: <code>{{nestedText(crossModelModels.a,'resolved_revision')||'not supplied by loader'}}</code></p><p>Weights: <code>{{nestedText(crossModelModels.a,'weights_sha256')||'unavailable'}}</code></p></div>
<div class="analysis-card"><h3>Checkpoint B</h3><p><strong>{{nestedText(crossModelModels.b,'repo_id_requested')||'—'}}</strong></p><p>Resolved revision: <code>{{nestedText(crossModelModels.b,'resolved_revision')||'not supplied by loader'}}</code></p><p>Weights: <code>{{nestedText(crossModelModels.b,'weights_sha256')||'unavailable'}}</code></p></div>
</div>
<div class="analysis-grid">
<div class="analysis-card"><h3>Next-token prediction</h3><p>A: <code>{{nestedText(crossModelPredictions.model_a_top,'token')||'—'}}</code> · p={{fmt(nestedNumber(crossModelPredictions.model_a_top,'probability')??null)}}</p><p>B: <code>{{nestedText(crossModelPredictions.model_b_top,'token')||'—'}}</code> · p={{fmt(nestedNumber(crossModelPredictions.model_b_top,'probability')??null)}}</p><p>Decoded top token match: <strong>{{crossModelPredictions.top_token_match===true?'yes':crossModelPredictions.top_token_match===false?'no':'not measured'}}</strong></p></div>
<div class="analysis-card"><h3>Logit distribution</h3><p>KL divergence A → B: <strong>{{fmt(asNumber(crossModelLogits.kl_divergence_a_to_b)??null)}}</strong></p><p class="hint">{{asString(crossModelLogits.not_comparable_reason)||'Computed from real next-token logits where tokenizer and vocabulary identities match.'}}</p></div>
</div>
<h3>Aligned residual layers ({{crossModelResidualRows.length}})</h3>
<div v-if="crossModelResidualRows.length" class="table-wrap"><table><thead><tr><th>Layer A/B</th><th>Tensor shape</th><th>Cosine similarity</th><th>Mean absolute difference</th></tr></thead><tbody><tr v-for="r in crossModelResidualRows" :key="'cross-resid-'+r.layer_a"><td>{{r.layer_a}} / {{r.layer_b}}</td><td><code>{{asArray(r.shape).join(' × ')}}</code></td><td>{{fmt(asNumber(r.cosine_similarity)??null)}}</td><td>{{fmt(asNumber(r.mean_absolute_difference)??null)}}</td></tr></tbody></table></div><p v-else class="hint">{{asString(crossModelResiduals.not_comparable_reason)||'No residual tensors aligned for this pair.'}}</p>
<h3>Aligned attention layers ({{crossModelAttentionRows.length}})</h3>
<div v-if="crossModelAttentionRows.length" class="table-wrap"><table><thead><tr><th>Layer A/B</th><th>Tensor shape</th><th>Tensor cosine</th><th>Mean absolute difference</th></tr></thead><tbody><tr v-for="r in crossModelAttentionRows" :key="'cross-attn-'+r.layer_a"><td>{{r.layer_a}} / {{r.layer_b}}</td><td><code>{{asArray(r.shape).join(' × ')}}</code></td><td>{{fmt(asNumber(r.tensor_cosine_similarity)??null)}}</td><td>{{fmt(asNumber(r.mean_absolute_difference)??null)}}</td></tr></tbody></table></div><p v-else class="hint">{{asString(crossModelAttention.not_comparable_reason)||'No attention tensors aligned for this pair.'}}</p>
<p class="hint">Input SHA-256: <code>{{nestedText(crossModelResult.input,'sha256')||'not supplied'}}</code> · Experiment record: <code>{{asString(crossModelResult.experiment_id)||'not supplied'}}</code> · Stored: {{crossModelResult.stored===true?'yes':crossModelResult.stored===false?'no':'not reported'}}</p>
</div>
</section>
<div class="results"><section class="panel"><div class="heading"><div><p class="eyebrow">02 / LAYER PROJECTIONS</p><h2>Logit Lens comparison</h2></div><span class="tag">{{lens.length}} / 2</span></div><p class="hint">Top returned token and probability per layer. These are intermediate projections, not final model predictions.</p><div v-if="!lens.length" class="empty">Run the prompt comparison to request live layer projections.</div><div v-else class="table-wrap"><table><thead><tr><th>Layer</th><th>A token</th><th>A p</th><th>B token</th><th>B p</th></tr></thead><tbody><tr v-for="r in lensRows" :key="r.layer" :class="{selected:selectedLayer===r.layer}" @click="selectedLayer=r.layer"><th>L{{r.layer}}</th><td><code>{{r.a}}</code></td><td>{{fmt(r.ap)}}</td><td><code>{{r.b}}</code></td><td>{{fmt(r.bp)}}</td></tr></tbody></table></div></section>
<section class="panel"><div class="heading"><div><p class="eyebrow">03 / SPARSE FEATURES</p><h2>SAE feature comparison</h2></div><span class="tag">{{sae.length}} / 2</span></div><p class="hint">Only returned feature indices and activations are displayed. Select a row to link to SAE Lab.</p><div v-if="!sae.length" class="empty">Run SAE inspection to compare feature activations.</div><div v-else class="table-wrap"><table><thead><tr><th>Feature</th><th>A activation</th><th>B activation</th><th>Δ B − A</th></tr></thead><tbody><tr v-for="r in saeRows" :key="r.index" :class="{selected:feature===r.index}" @click="feature=r.index"><th>F{{r.index}}</th><td>{{fmt(r.a)}}</td><td>{{fmt(r.b)}}</td><td>{{fmt(r.delta)}}</td></tr></tbody></table></div><button v-if="feature!==null" class="text-link" @click="openTool('saelab')">Inspect feature F{{feature}} in SAE Lab →</button></section></div>
<section class="panel"><div class="heading"><div><p class="eyebrow">04 / DIFFERENCE ANALYSIS</p><h2>Quantitative comparison</h2></div><span class="tag">{{differenceSummary}}</span></div>
<p class="hint">Differences are computed only where both prompt responses contain a finite numeric value. Missing or non-aligned values remain “—”; they are never treated as zero.</p>
<div class="analysis-grid">
<div class="analysis-card"><h3>Per-layer probability changes</h3><p class="hint">Difference between the top returned token probabilities, B − A. Tokens may differ between prompts, so compare this as top-token confidence change, not probability of the same token.</p><div v-if="!lensRows.length" class="empty">Run Logit Lens comparison first.</div><div v-else class="heatmap-scroll"><table class="heatmap-table"><thead><tr><th>Layer</th><th>A p</th><th>B p</th><th>Δ B − A</th><th>Top-token change</th></tr></thead><tbody><tr v-for="r in lensRows" :key="'prob-'+r.layer"><th>L{{r.layer}}</th><td>{{fmt(r.ap)}}</td><td>{{fmt(r.bp)}}</td><td :class="deltaClass(r.probabilityDelta)">{{fmt(r.probabilityDelta)}}</td><td><span class="token-pair"><code>{{r.a}}</code><span>→</span><code>{{r.b}}</code></span></td></tr></tbody></table></div></div>
<div class="analysis-card"><h3>SAE feature difference heatmap</h3><p class="hint">Rows are returned feature indices; A and B columns show activations and the delta. Cell intensity is scaled to the largest absolute observed delta in this comparison.</p><div v-if="!saeRows.length" class="empty">Run SAE inspection first.</div><div v-else class="heatmap-scroll"><table class="heatmap-table"><thead><tr><th>Feature</th><th>A</th><th>B</th><th>Δ</th><th>Relative Δ</th></tr></thead><tbody><tr v-for="r in rankedSaeRows" :key="'feature-'+r.index"><th>F{{r.index}}</th><td>{{fmt(r.a)}}</td><td>{{fmt(r.b)}}</td><td :style="heatStyle(r.delta)">{{fmt(r.delta)}}</td><td><div class="delta-track"><span :style="{width:deltaWidth(r.delta)+'%'}"></span></div></td></tr></tbody></table></div><p class="hint">Ranked by absolute activation change. Missing values are excluded from ranking and shown as “—”.</p></div>
</div>
</section>
<section class="panel" data-testid="residual-activation-comparison"><div class="heading"><div><p class="eyebrow">05 / LIVE RESIDUAL STREAM</p><h2>Token × residual-dimension difference heatmap</h2></div><span class="tag">{{activationComparison ? 'WEIGHT-FINGERPRINT MATCHED' : 'AWAITING CAPTURE'}}</span></div><p class="hint">Captures the backend's full per-token <code>resid_post</code> tensor for both prompts at the selected GPT-2 layer. Each visible cell is B − A for the same token position and residual dimension. Capture is rejected unless both responses are live, attested, and carry the same weight-derived model fingerprint. This backend only loads its configured GPT-2 checkpoint; it cannot switch arbitrary GPT-2/SAE checkpoint IDs.</p><div class="fields"><label>Transformer layer<input v-model.number="activationLayer" type="number" min="0" max="11" step="1"></label><label>First residual dimension<input v-model.number="activationDimensionStart" type="number" min="0" :max="Math.max(0, activationDimensionCount-1)" step="32"></label></div><div class="actions"><button class="button primary" :disabled="activationLoading||!promptA.trim()||!promptB.trim()" @click="runActivationComparison">{{activationLoading?'Capturing live tensors…':'Capture residual difference'}}</button></div><p v-if="activationError" class="error" role="alert">{{activationError}}</p><div v-if="activationComparison" class="activation-result"><p class="notice">Loaded model: <strong>{{activationComparison.model}}</strong> · weight fingerprint <code>{{activationComparison.fingerprint.slice(0,16)}}…</code> · layer {{activationLayer}} · showing dimensions {{activationDimensionStart}}–{{Math.min(activationDimensionStart+31, activationDimensionCount-1)}}</p><div class="heatmap-scroll"><table class="heatmap-table residual-heatmap"><thead><tr><th>Token position</th><th>Prompt A token</th><th>Prompt B token</th><th v-for="dim in visibleDimensions" :key="dim">d{{dim}}</th></tr></thead><tbody><tr v-for="row in residualRows" :key="row.token"><th>#{{row.token}}</th><td><code>{{row.aToken || '—'}}</code></td><td><code>{{row.bToken || '—'}}</code></td><td v-for="cell in row.cells" :key="cell.dimension" :title="cell.delta===null?'Not aligned / missing':'d'+cell.dimension+': '+cell.delta" :style="residualHeatStyle(cell.delta)">{{fmt(cell.delta)}}</td></tr></tbody></table></div><p class="hint">Showing up to 32 token positions and 32 dimensions per view. Token positions are aligned by index, not token text. Tokenization differences remain visible in the A/B token columns; unmatched rows and missing numeric cells are shown as “—”, never as zero. The underlying capture retains the complete returned residual matrices for both prompts.</p></div><div v-else class="empty">No residual-stream comparison yet. Capture both prompts against the same verified backend checkpoint.</div></section>
<section class="panel"><div class="heading"><div><p class="eyebrow">06 / REPRODUCIBILITY</p><h2>Save experiment and export findings</h2></div><span class="tag">{{hasFindings?'FINDINGS READY':'DRAFT'}}</span></div><label class="notes">Research notes<textarea v-model="notes" rows="3" placeholder="Hypothesis, observations, caveats, next steps…"></textarea></label><div class="actions"><button class="button primary" :disabled="saving||!title.trim()" @click="save">{{saving?'Saving…':'Save to MECH experiments'}}</button><button class="button secondary" :disabled="!hasFindings" @click="exportFindings">Export JSON</button></div><p v-if="saved" class="notice" role="status">{{saved}}</p><p class="hint">Persistence uses the existing MECH experiments API; JSON export includes inputs, results, provenance, and notes.</p></section>
<section class="panel"><div class="heading"><div><p class="eyebrow">07 / CONTINUE ANALYSIS</p><h2>Linked MECH tools</h2></div></div><div class="tools"><button v-for="t in tools" :key="t.id" class="tool" @click="openTool(t.id)"><strong>{{t.name}}</strong><span>{{t.description}}</span><b>Open →</b></button></div></section>
</section>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {api} from '../services/api';
import {asArray,asNumber,asString,gpt2LayerActivations,gpt2LogitLensAll,isRecord,numberMatrix,saeInspect,statusOf,type JsonRecord} from '../services/interpretabilityClient';
import {setResearchSelection} from '../services/researchSelectionContext';
const title=ref('Prompt and checkpoint comparison'),checkpoint=ref(''),checkpointB=ref(''),promptA=ref(''),promptB=ref(''),layer=ref(''),source=ref(''),notes=ref(''),lens=ref<Array<{prompt:string;record:JsonRecord}>>([]),sae=ref<Array<{prompt:string;record:JsonRecord;features:Array<{index:number;value:number|null}>}>>([]),running=ref(false),saving=ref(false),error=ref(''),notice=ref(''),saved=ref(''),backendLabel=ref('READY TO RUN'),feature=ref<number|null>(null),selectedLayer=ref<number|null>(null);
const activationLayer=ref(0),activationDimensionStart=ref(0),activationLoading=ref(false),activationError=ref(''),activationComparison=ref<{a:JsonRecord;b:JsonRecord;model:string;fingerprint:string}|null>(null);
const promptRotationNote=ref('Waiting for live GPT-2 prompt generation…'),promptRotationBusy=ref(false);
let promptRotationTimer:ReturnType<typeof setInterval>|null=null;
const compareModelA=ref(''),compareModelB=ref(''),compareRevisionA=ref('main'),compareRevisionB=ref('main');
const crossModelBusy=ref(false),crossModelError=ref(''),crossModelResult=ref<JsonRecord|null>(null);
const crossModelModels=computed(()=>isRecord(crossModelResult.value?.models)?crossModelResult.value!.models as JsonRecord:{});
const crossModelPredictions=computed(()=>isRecord(crossModelResult.value?.predictions)?crossModelResult.value!.predictions as JsonRecord:{});
const crossModelLogits=computed(()=>isRecord(crossModelResult.value?.logits)?crossModelResult.value!.logits as JsonRecord:{});
const crossModelResiduals=computed(()=>isRecord(crossModelResult.value?.residuals)?crossModelResult.value!.residuals as JsonRecord:{});
const crossModelAttention=computed(()=>isRecord(crossModelResult.value?.attention)?crossModelResult.value!.attention as JsonRecord:{});
const crossModelResidualRows=computed(()=>asArray(crossModelResiduals.value.layers).filter(isRecord));
const crossModelAttentionRows=computed(()=>asArray(crossModelAttention.value.layers).filter(isRecord));
function nestedText(value:unknown,key:string):string{return isRecord(value)?asString(value[key]):''}
function nestedNumber(value:unknown,key:string):number|null{return isRecord(value)?asNumber(value[key])??null:null}


const hasFindings=computed(()=>lens.value.length>0||sae.value.length>0||activationComparison.value!==null);
const activationDimensionCount=computed(()=>Math.max(0,numberMatrix(activationComparison.value?.a.resid_post).reduce((max,row)=>Math.max(max,row.length),0)));
const visibleDimensions=computed(()=>Array.from({length:Math.min(32,Math.max(0,activationDimensionCount.value-activationDimensionStart.value))},(_,i)=>activationDimensionStart.value+i));
const residualRows=computed(()=>{if(!activationComparison.value)return[];const a=numberMatrix(activationComparison.value.a.resid_post),b=numberMatrix(activationComparison.value.b.resid_post),at=asArray(activationComparison.value.a.tokens),bt=asArray(activationComparison.value.b.tokens),count=Math.min(32,Math.max(a.length,b.length));return Array.from({length:count},(_,token)=>({token,aToken:typeof at[token]==='string'?at[token] as string:'',bToken:typeof bt[token]==='string'?bt[token] as string:'',cells:visibleDimensions.value.map(dimension=>({dimension,delta:typeof a[token]?.[dimension]==='number'&&typeof b[token]?.[dimension]==='number'?b[token][dimension]!-a[token][dimension]!:null}))}));});
const differenceSummary=computed(()=>{const matchedLens=lensRows.value.filter(r=>r.probabilityDelta!==null).length;const matchedSae=saeRows.value.filter(r=>r.delta!==null).length;return `${matchedLens} layer deltas · ${matchedSae} feature deltas`});
const tools=[{id:'activations',name:'Live Activation Inspector',description:'Token heatmaps and activation statistics'},{id:'logitlens',name:'Logit Lens',description:'Intermediate token predictions'},{id:'saelab',name:'SAE Lab',description:'Sparse features and checkpoint status'},{id:'transformer',name:'Transformer Visualizer',description:'Attention heads and layer topology'},{id:'circuitexplorer',name:'Circuit Explorer',description:'Inspect registered mechanisms'},{id:'experiments',name:'Experiments',description:'Review backend experiment records'},{id:'neuroninspector',name:'Neural Network Workspace',description:'Explore layer and neuron structure'}];
const lensRows=computed(()=>{const read=(x:typeof lens.value[number]|undefined)=>new Map((x?asArray(x.record.layers).filter(isRecord):[]).map(r=>[asNumber(r.layer)??-1,r]));const a=read(lens.value[0]),b=read(lens.value[1]);return [...new Set([...a.keys(),...b.keys()])].filter(n=>n>=0).sort((x,y)=>x-y).map(layer=>{const x=a.get(layer),y=b.get(layer),xt=x?asArray(x.top_k_tokens).filter(isRecord)[0]:undefined,yt=y?asArray(y.top_k_tokens).filter(isRecord)[0]:undefined;return{layer,a:x?asString(x.top_token)||asString(xt?.token)||'—':'—',ap:x?asNumber(x.top_token_prob)??asNumber(xt?.prob):null,b:y?asString(y.top_token)||asString(yt?.token)||'—':'—',bp:y?asNumber(y.top_token_prob)??asNumber(yt?.prob):null,probabilityDelta:(x?(asNumber(x.top_token_prob)??asNumber(xt?.prob)):null)!==null&&(y?(asNumber(y.top_token_prob)??asNumber(yt?.prob)):null)!==null?((y?(asNumber(y.top_token_prob)??asNumber(yt?.prob)):null)!-(x?(asNumber(x.top_token_prob)??asNumber(xt?.prob)):null)!):null}})});
function featureRows(record:JsonRecord){const ids=asArray(record.feature_indices),values=asArray(record.activations);return ids.map((id,i)=>({index:asNumber(id)??i,value:asNumber(values[i])}))}
const saeRows=computed(()=>{const map=(x:typeof sae.value[number]|undefined)=>new Map((x?.features??[]).map(f=>[f.index,f.value]));const a=map(sae.value[0]),b=map(sae.value[1]);return [...new Set([...a.keys(),...b.keys()])].sort((x,y)=>x-y).slice(0,100).map(index=>({index,a:a.get(index)??null,b:b.get(index)??null,delta:a.get(index)!=null&&b.get(index)!=null?b.get(index)!-a.get(index)!:null}))});
const rankedSaeRows=computed(()=>[...saeRows.value].sort((a,b)=>{if(a.delta===null)return b.delta===null?a.index-b.index:1;if(b.delta===null)return -1;return Math.abs(b.delta)-Math.abs(a.delta)}));
function deltaWidth(v:number|null){if(v===null)return 0;const max=Math.max(1e-12,...saeRows.value.map(r=>Math.abs(r.delta??0)));return Math.abs(v)/max*100}
function heatStyle(v:number|null){if(v===null)return {background:'var(--surface-2)',color:'var(--text-muted)'};const strength=Math.min(.8,Math.abs(v)/Math.max(1e-12,...saeRows.value.map(r=>Math.abs(r.delta??0)))*.8);return {background:v>=0?`rgba(37,99,235,${strength})`:`rgba(217,119,87,${strength})`,color:strength>.48?'#fff':'var(--text)'}}
function deltaClass(v:number|null){return v===null?'missing':v>0?'delta-positive':v<0?'delta-negative':'delta-neutral'}
function verifiedFingerprint(record:JsonRecord):{model:string;fingerprint:string}|null{const measurement=record.measurement_record;if(!isRecord(measurement)||!isRecord(measurement.model_identity))return null;const identity=measurement.model_identity,model=asString(identity.name),fingerprint=asString(identity.content_hash),source=asString(identity.content_hash_source);if(record.provenance!=='live'||record.attested!==true||!model||!fingerprint||!source||source==='model_name_fallback')return null;return{model,fingerprint}}
async function runActivationComparison(){activationLoading.value=true;activationError.value='';activationComparison.value=null;try{if(!Number.isInteger(activationLayer.value)||activationLayer.value<0)throw Error('Layer must be a non-negative integer.');if(!Number.isInteger(activationDimensionStart.value)||activationDimensionStart.value<0)throw Error('Residual dimension must be a non-negative integer.');const [a,b]=await Promise.all([gpt2LayerActivations({prompt:promptA.value.trim(),layer:activationLayer.value}),gpt2LayerActivations({prompt:promptB.value.trim(),layer:activationLayer.value})]);if(statusOf(a)!=='ok'||statusOf(b)!=='ok')throw Error('The backend did not return both live residual tensors: '+(asString(a.error)||asString(a.reason)||statusOf(a)||'A failed')+'; '+(asString(b.error)||asString(b.reason)||statusOf(b)||'B failed')+'.');const ia=verifiedFingerprint(a),ib=verifiedFingerprint(b);if(!ia||!ib)throw Error('Refusing to draw a checkpoint comparison: both tensor responses must carry backend-issued live attestation and a weight-derived model fingerprint. The backend did not provide verifiable identity metadata.');if(ia.model!==ib.model||ia.fingerprint!==ib.fingerprint)throw Error('Refusing to subtract incompatible activations: the captures came from different loaded models or weight fingerprints.');const am=numberMatrix(a.resid_post),bm=numberMatrix(b.resid_post);if(!am.length||!bm.length||!am[0]?.length||!bm[0]?.length)throw Error('The backend did not return non-empty resid_post matrices.');if(am.some(row=>row.length!==am[0].length)||bm.some(row=>row.length!==bm[0].length)||am[0].length!==bm[0].length)throw Error('Residual tensor dimensions are incompatible; no heatmap was produced.');activationComparison.value={a,b,model:ia.model,fingerprint:ia.fingerprint};activationDimensionStart.value=Math.min(activationDimensionStart.value,Math.max(0,am[0].length-1));notice.value='Residual-stream tensors captured and weight fingerprints matched.'}catch(e){activationError.value=e instanceof Error?e.message:String(e)}finally{activationLoading.value=false}}
function residualHeatStyle(v:number|null){if(v===null)return{background:'var(--surface-2)',color:'var(--text-muted)'};const max=Math.max(1e-12,...residualRows.value.flatMap(r=>r.cells.map(c=>Math.abs(c.delta??0))));const strength=Math.min(.85,Math.abs(v)/max*.85);return{background:v>=0?'rgba(37,99,235,'+strength+')':'rgba(217,119,87,'+strength+')',color:strength>.48?'#fff':'var(--text)'}}
async function runLens(){running.value=true;error.value='';notice.value='';lens.value=[];try{const out=[];for(const prompt of [promptA.value.trim(),promptB.value.trim()]){const record=await gpt2LogitLensAll({prompt});if(statusOf(record)!=='ok')throw Error(asString(record.error)||asString(record.reason)||'Logit Lens request failed.');out.push({prompt,record})}lens.value=out;backendLabel.value='LIVE API RESPONDED';notice.value='Both projections returned successfully.'}catch(e){backendLabel.value='API ERROR';error.value=e instanceof Error?e.message:String(e)}finally{running.value=false}}
async function runSae(){running.value=true;error.value='';notice.value='';sae.value=[];try{const out=[];for(const [index,prompt] of [promptA.value.trim(),promptB.value.trim()].entries()){const payload:Record<string,unknown>={prompt};if(layer.value.trim()){const n=Number(layer.value);if(!Number.isInteger(n)||n<0)throw Error('Layer must be a non-negative integer.');payload.layer=n}if(source.value.trim())payload.source=source.value.trim();const selectedCheckpoint=(index===1&&checkpointB.value.trim())?checkpointB.value.trim():checkpoint.value.trim();if(selectedCheckpoint)payload.identifier=selectedCheckpoint;const record=await saeInspect(payload);if(statusOf(record)!=='completed')throw Error(asString(record.reason)||asString(record.error)||'SAE inspection did not complete.');out.push({prompt,record,features:featureRows(record)})}sae.value=out;backendLabel.value='LIVE API RESPONDED';notice.value=checkpointB.value.trim()?'SAE results returned for the requested A/B checkpoint identifiers. Feature identities and layer compatibility still depend on the backend checkpoint metadata.':'Both SAE captures completed using checkpoint A.'}catch(e){backendLabel.value='API ERROR';error.value=e instanceof Error?e.message:String(e)}finally{running.value=false}}
function snapshot(){return{schema_version:1,exported_at:new Date().toISOString(),title:title.value,model_or_checkpoint:checkpoint.value,inputs:{prompt_a:promptA.value,prompt_b:promptB.value,checkpoint_a:checkpoint.value,checkpoint_b:checkpointB.value||checkpoint.value,sae_layer:layer.value||null,sae_source:source.value||null},logit_lens:lens.value.map(x=>({prompt:x.prompt,provenance:x.record.provenance??null,method:x.record.method??null,layers:x.record.layers??[]})),sae:sae.value.map(x=>({prompt:x.prompt,provenance:x.record.provenance??null,features:x.features})),residual_activation_comparison:activationComparison.value?{layer:activationLayer.value,model:activationComparison.value.model,weight_fingerprint:activationComparison.value.fingerprint,prompt_a:promptA.value,prompt_b:promptB.value,provenance_a:activationComparison.value.a.provenance,provenance_b:activationComparison.value.b.provenance,measurement_record_a:activationComparison.value.a.measurement_record,measurement_record_b:activationComparison.value.b.measurement_record,resid_post_a:activationComparison.value.a.resid_post,resid_post_b:activationComparison.value.b.resid_post,tokens_a:activationComparison.value.a.tokens,tokens_b:activationComparison.value.b.tokens}:null,notes:notes.value}}
async function save(){saving.value=true;saved.value='';try{const result=await api.createExperiment({id:typeof crypto!=='undefined'&&'randomUUID'in crypto?'research-'+crypto.randomUUID():'research-'+Date.now(),title:title.value.trim(),targetCircuit:'research-workflow',status:hasFindings.value?'completed':'draft',createdAt:new Date().toISOString(),model:checkpoint.value,prompts:[promptA.value,promptB.value],notes:notes.value,results:snapshot()});if(isRecord(result)&&result.error!==undefined)throw Error(asString(result.error)||'Backend rejected the record.');saved.value='Saved to MECH backend experiments.'}catch(e){saved.value='Save failed: '+(e instanceof Error?e.message:String(e));error.value=saved.value}finally{saving.value=false}}
function exportFindings(){const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='mech-research-findings.json';a.click();URL.revokeObjectURL(url)}
function openTool(id:string){setResearchSelection({prompt:promptA.value.trim(),checkpoint:feature.value!==null&&checkpointB.value.trim()?checkpointB.value.trim():checkpoint.value.trim(),source:source.value.trim()||undefined,layer:selectedLayer.value ?? (layer.value.trim()?Number(layer.value):undefined),feature:feature.value??undefined,origin:'research-workflow'});window.location.hash=id}
function fmt(v:number|null|undefined){return v==null||!Number.isFinite(v)?'—':v.toLocaleString(undefined,{maximumFractionDigits:5})}

async function createGpt2Prompt():Promise<string>{
  const response=await api.gpt2FreshPrompt();
  if(!isRecord(response)||response.status!=='ok'||response.provenance!=='live') {
    throw new Error(isRecord(response)?asString(response.error)||asString(response.reason)||'GPT-2 prompt generation is unavailable.':'GPT-2 returned an unreadable response.');
  }
  const text=asString(response.prompt)?.trim();
  if(!text) throw new Error('GPT-2 returned no prompt text; no canned prompt was substituted.');
  return text;
}
async function rotateResearchPrompts():Promise<void>{
  if(promptRotationBusy.value)return;
  promptRotationBusy.value=true;
  try{
    const nextA=await createGpt2Prompt();
    let nextB=await createGpt2Prompt();
    for(let attempt=0;nextB===nextA&&attempt<2;attempt++) nextB=await createGpt2Prompt();
    promptA.value=nextA;
    promptB.value=nextB;
    promptRotationNote.value='Both prompts were generated by live GPT-2 · '+new Date().toLocaleTimeString();
  }catch(e){
    promptRotationNote.value='GPT-2 prompt generation unavailable: '+(e instanceof Error?e.message:String(e));
  }finally{promptRotationBusy.value=false}
}
async function runCrossModelComparison():Promise<void>{
  crossModelError.value='';
  crossModelResult.value=null;
  const prompt=promptA.value.trim(),modelA=compareModelA.value.trim(),modelB=compareModelB.value.trim();
  if(!prompt){crossModelError.value='Waiting for a prompt generated by live GPT-2.';return}
  if(!modelA||!modelB){crossModelError.value='Enter two Hugging Face checkpoint IDs. No default checkpoints are silently selected.';return}
  if(modelA===modelB&&compareRevisionA.value.trim()===compareRevisionB.value.trim()){
    crossModelError.value='Choose two distinct checkpoint/revision selections for an independent comparison.';return
  }
  crossModelBusy.value=true;
  try{
    const result=await api.compareModels({
      prompt,model_a:modelA,model_b:modelB,
      revision_a:compareRevisionA.value.trim()||'main',
      revision_b:compareRevisionB.value.trim()||'main',
    });
    if(!isRecord(result))throw new Error('The comparison API returned an unreadable response.');
    if(result.status!=='completed'||result.provenance!=='live'||result.measured!==true){
      throw new Error(asString(result.reason)||asString(result.error)||'The two live checkpoints could not be compared. No synthetic results were returned.');
    }
    crossModelResult.value=result;
    notice.value=result.stored===true?'Live comparison measured and stored in MECH experiments.':'Live comparison measured; persistence needs attention.';
  }catch(e){crossModelError.value=e instanceof Error?e.message:String(e)}
  finally{crossModelBusy.value=false}
}
onMounted(()=>{
  void rotateResearchPrompts();
  promptRotationTimer=setInterval(()=>{void rotateResearchPrompts()},120_000);
});
onBeforeUnmount(()=>{
  if(promptRotationTimer!==null)clearInterval(promptRotationTimer);
});
</script>
